// 開局領場次憑證：確認 LINE 身分與活動期間後，簽一張 HMAC 憑證（含使用者、開始時間、一次性編號）。
// ⬇️ 換成一串夠長的隨機字串，且必須與「Validate & Rank」節點的 SECRET 相同。
const SECRET = 'CHANGE_ME_TO_A_LONG_RANDOM_STRING';
const EVENT_START = Date.parse('2026-10-25T00:00:00+08:00');
const EVENT_END = Date.parse('2026-11-01T00:00:00+08:00');

const crypto = require('crypto');
const v = $input.first().json;
const user = v.statusCode === 200 && v.body && v.body.sub ? v.body : null;
if (!user) return [{ json: { response: { ok: false, error: 'invalid_token' } } }];

const now = Date.now();
if (now < EVENT_START || now >= EVENT_END) {
  return [{ json: { response: { ok: false, error: 'out_of_window' } } }];
}

const payload = Buffer.from(JSON.stringify({
  u: user.sub,
  iat: now,
  n: crypto.randomBytes(9).toString('base64url'),
})).toString('base64url');
const sig = crypto.createHmac('sha256', SECRET).update(payload).digest('base64url');
return [{ json: { response: { ok: true, session: payload + '.' + sig } } }];

// 驗證一局成績並計算排行榜。
// 輸入：Data Table 的所有成績列（$input）；另外讀 Webhook 的請求與 LINE 驗證結果。
// 輸出：{ store: 是否寫入成績, row: 要寫入的成績列, response: 回給遊戲的 JSON }
// ⬇️ 必須與「Sign Session」節點的 SECRET 相同。
const SECRET = 'CHANGE_ME_TO_A_LONG_RANDOM_STRING';
const EVENT_START = Date.parse('2026-10-25T00:00:00+08:00');
const EVENT_END = Date.parse('2026-11-01T00:00:00+08:00');
const EVENT_TYPES = ['normal', 'hard'];   // 計入活動的難度，各自排名
const GAME_MS = 30000;
// 與 halloween/js/characters.js 一致：[分數, 是否加分]
const CHARS = { cat: [10, true], bat: [10, true], owl: [15, true], rabbit: [20, true], skull: [15, false], ghost: [10, false] };

const crypto = require('crypto');
const req = $('Score Webhook').first().json.body || {};
const v = $('LINE Verify (score)').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.userId);
const now = Date.now();

const user = v.statusCode === 200 && v.body && v.body.sub ? v.body : null;
if (!user) return [{ json: { store: false, row: {}, response: { ok: false, error: 'invalid_token' } } }];

// —— 場次憑證 ——
function readSession(tok) {
  if (typeof tok !== 'string') return null;
  const [p, sig] = tok.split('.');
  if (!p || !sig) return null;
  const good = crypto.createHmac('sha256', SECRET).update(p).digest('base64url');
  if (sig.length !== good.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(good))) return null;
  try { return JSON.parse(Buffer.from(p, 'base64url').toString()); } catch (e) { return null; }
}

// —— 依打擊紀錄重算分數（規則同 halloween/js/game.js） ——
function replay(log) {
  if (!Array.isArray(log) || log.length > 160) return null;
  let score = 0, combo = 0, bestCombo = 0, hits = 0, bad = 0, lastT = 0, lastHitT = -1e9;
  for (const e of log) {
    const c = e && CHARS[e.k];
    if (!c || typeof e.t !== 'number' || e.t < lastT || e.t > GAME_MS + 500) return null;
    lastT = e.t;
    if (e.x) { if (c[1]) combo = 0; continue; }       // 好角色逃走：連擊歸零
    if (e.t - lastHitT < 60) return null;             // 人手連點不會這麼快
    lastHitT = e.t;
    if (c[1]) {
      combo++; hits++; bestCombo = Math.max(bestCombo, combo);
      score += c[0] * (1 + Math.min(3, Math.floor(combo / 5)));
    } else {
      combo = 0; bad++;
      score = Math.max(0, score - c[0]);
    }
  }
  return { score, hits, bad, bestCombo };
}

const ses = readSession(req.session);
let reason = '';
let replayed = null;
if (!ses || ses.u !== user.sub) reason = 'bad_session';
else if (ses.iat < EVENT_START || ses.iat >= EVENT_END) reason = 'out_of_window';
else if (!EVENT_TYPES.includes(req.type)) reason = 'wrong_type';
else if (rows.some((r) => r.nonce === ses.n)) reason = 'replayed';
else if (now - ses.iat < GAME_MS - 2000) reason = 'too_fast';     // 預留網路延遲
else if (now - ses.iat > 30 * 60 * 1000) reason = 'bad_session';  // 憑證 30 分鐘內有效
else {
  replayed = replay(req.log);
  if (!replayed) reason = 'bad_log';
  else if (replayed.score !== req.score) reason = 'score_mismatch';
}

const row = {
  playedAt: new Date(now).toISOString(),
  type: String(req.type || ''),
  userId: user.sub,
  name: String(user.name || ''),
  score: Number(req.score) || 0,
  hits: replayed ? replayed.hits : Number(req.hits) || 0,
  bad: replayed ? replayed.bad : Number(req.bad) || 0,
  bestCombo: replayed ? replayed.bestCombo : Number(req.bestCombo) || 0,
  status: reason ? 'rejected' : 'ok',
  reason,
  nonce: ses ? String(ses.n) : '',
};

// —— 排行榜：同一難度內每人取最高分；同分以伺服器先收到者為準（只有第一位達到最高分的人是第一名） ——
function mask(name) {
  const c = Array.from(String(name || '').trim());
  if (!c.length) return '玩家';
  if (c.length === 1) return c[0] + '*';
  if (c.length === 2) return c[0] + '*';
  return c[0] + '*'.repeat(Math.min(c.length - 2, 3)) + c[c.length - 1];
}

const best = new Map();
for (const r of rows.concat(reason ? [] : [row])) {
  if (r.status !== 'ok' || r.type !== row.type) continue;
  const s = Number(r.score) || 0;
  const cur = best.get(r.userId);
  if (!cur || s > cur.score || (s === cur.score && r.playedAt < cur.playedAt)) {
    best.set(r.userId, { userId: r.userId, name: r.name, score: s, playedAt: r.playedAt });
  }
}
const ranked = [...best.values()].sort((a, b) => b.score - a.score || (a.playedAt < b.playedAt ? -1 : 1));
const myIdx = ranked.findIndex((x) => x.userId === user.sub);

const response = {
  ok: !reason,
  reason: reason || undefined,
  total: ranked.length,
  me: myIdx >= 0 ? { rank: myIdx + 1, best: ranked[myIdx].score, name: mask(ranked[myIdx].name) } : null,
  top: ranked.slice(0, 10).map((x, i) => ({ rank: i + 1, name: mask(x.name), score: x.score, me: x.userId === user.sub })),
};

return [{ json: { store: true, row, response } }];
